/**
 * calibration-loop.ts — 校准闭环
 *
 * P3-03: 把"诊断→行动→效果→基线更新"串成自动化闭环。
 *
 * 对标 Claw-Code RecoveryRecipes: 每次诊断后自动检查上次建议是否被采纳、
 * 采纳后效果如何、基线是否需要修正。支持"反馈回放"——用户说"上次判断不对"，
 * 系统回溯当时的数据和修正模型。
 *
 * 三层校准:
 *   Layer 1 (即时): 单次诊断后，采纳率 < 阈值 → 下次建议策略调整
 *   Layer 2 (周期): 3+ 次诊断后，EvolutionSignal → 基线自动修正
 *   Layer 3 (全局): 跨组织联邦进化（后续）
 */
export interface CalibrationCheck {
    checkId: string;
    orgId: string;
    teamId: string;
    /** 检查类型 */
    checkType: 'adoption_feedback' | 'baseline_drift' | 'terminology_shift' | 'pattern_conflict';
    /** 检查结果 */
    passed: boolean;
    /** 发现描述 */
    finding: string;
    /** 建议修正 */
    recommendedAction: string;
    /** 是否需要人工确认 */
    requiresHumanReview: boolean;
    /** 置信度 */
    confidence: number;
    /** 生成时间 */
    generatedAt: string;
}
export interface CalibrationReport {
    reportId: string;
    orgId: string;
    teamId: string;
    diagnosisCount: number;
    checks: CalibrationCheck[];
    /** 自动修正项 */
    autoCorrections: Array<{
        field: string;
        from: any;
        to: any;
        reason: string;
    }>;
    /** 需人工确认项 */
    humanReviewItems: CalibrationCheck[];
    /** 总体校准状态 */
    overallStatus: 'calibrated' | 'needs_review' | 'drifting' | 'unstable';
    generatedAt: string;
}
export interface FeedbackReplay {
    replayId: string;
    orgId: string;
    /** 回放的诊断 ID */
    diagnosisId: string;
    /** 当时的诊断快照 */
    snapshot: {
        scores: Record<string, number>;
        hypotheses: string[];
        actions: string[];
        baseline: Record<string, number>;
    };
    /** 用户反馈 */
    userFeedback: {
        /** 哪些判断不准确 */
        inaccurateFindings: string[];
        /** 哪些建议不可行 */
        impracticalActions: string[];
        /** 用户修正建议 */
        corrections: string[];
    };
    /** 修正后的模型参数 */
    correctedParams: Record<string, number>;
    /** 回放时间 */
    replayedAt: string;
}
/**
 * 每次诊断完成后运行校准检查。
 * 检查上次诊断的建议是否被采纳、基线是否漂移、术语是否需要更新。
 */
export declare function runCalibrationCheck(orgId: string, teamId: string, diagnosisIds: string[], currentScores: Record<string, number>): CalibrationReport;
/**
 * 记录诊断快照，供后续回放使用。
 * 对标 Claw-Code Session JSONL 持久化——保留完整诊断上下文。
 */
export declare function recordDiagnosisSnapshot(orgId: string, diagnosisId: string, scores: Record<string, number>, hypotheses: string[], actions: string[], baseline: Record<string, number>): void;
/**
 * 用户反馈回放。用户说"上次 XX 判断不对"时调用。
 * 回溯当时的数据，记录反馈，修正模型参数。
 */
export declare function submitFeedbackReplay(diagnosisId: string, feedback: {
    inaccurateFindings: string[];
    impracticalActions: string[];
    corrections: string[];
}): FeedbackReplay | null;
/** 获取回放记录 */
export declare function getFeedbackReplay(diagnosisId: string): FeedbackReplay | undefined;
/** 清空（测试用） */
export declare function clearCalibrationStore(): void;
